// Polling data, grouped by race. Senate 2026 only for now; the shape is
// deliberately generic (raceType + optional district/seatClass) so House,
// governor, and presidential races can be added later without a schema change.
//
// SOURCE: RealClearPolling (realclearpolling.com). This file is meant to be
// regenerated by `pnpm polls:pull` (see scripts/pull-polls.mjs) -- do not
// hand-maintain it long-term. The entries below are a hand-seeded EXAMPLE for
// Ohio so the page has something to render; numbers need replacing with a real
// pull.

export type RaceType = "senate" | "house" | "governor" | "president";
export type PartyCode = "D" | "R" | "I" | "O";
export type PollPopulation = "LV" | "RV" | "A"; // likely / registered voters, adults

export interface PollResult {
  candidate: string;
  party: PartyCode;
  pct: number;
}

export interface Poll {
  pollster: string;
  /** ISO dates for the field period. */
  startDate: string;
  endDate: string;
  sampleSize?: number;
  population?: PollPopulation;
  /** Link to the poll or its source entry. */
  url?: string;
  /** Who paid for the poll, when disclosed. */
  sponsor?: string;
  /** Set when the poll is from/for a campaign or partisan group. */
  partisan?: PartyCode;
  results: PollResult[];
}

export interface RacePolls {
  raceType: RaceType;
  /** USPS state code. */
  state: string;
  /** House only. */
  district?: number;
  /** Senate only. */
  seatClass?: 1 | 2 | 3;
  special?: boolean;
  /** Display title, e.g. "Ohio Senate (special)". */
  title: string;
  candidates: { name: string; party: PartyCode; incumbent?: boolean }[];
  polls: Poll[];
  /** Aggregator this race's polls came from, if not the default RealClearPolling. */
  sourceNote?: string;
  /** The aggregator's own headline average, if the source publishes one. */
  aggregateAverage?: {
    spread: string;
    period: string;
    results: PollResult[];
  };
  /** Where the polls came from and when they were last refreshed. */
  source: string;
  lastPulled?: string;
  /** Election year. Absent means 2026 (the current cycle). */
  year?: number;
}

import generated from "~/data/polls.generated.json";
import { SEEDED_RACES } from "~/data/pollsSeeded";

/** Election year for a race — absent means the current 2026 cycle. */
export function raceYear(r: Pick<RacePolls, "year">): number {
  return r.year ?? 2026;
}

/** A stable key for a race, so a real pull can replace the seeded example.
 *  Includes `special` — Ohio's 2026 Senate ballot has both Sherrod Brown's
 *  regular-seat race and a separate special election for the seat Husted
 *  was appointed to; without `special` in the key they collide and the
 *  second one silently disappears (last one merged into `POLLS` wins). */
export function raceKey(
  r: Pick<RacePolls, "raceType" | "state" | "district" | "year" | "special">
): string {
  return `${raceYear(r)}:${r.raceType}:${r.state}:${r.district ?? ""}:${
    r.special ? "special" : ""
  }`;
}

/** Hand-seeded races (mostly U.S. House districts RCP has no page for).
 *  `pnpm polls:pull` fills polls.generated.json, whose races override these by
 *  key if a real pull ever covers them. */
const SEEDED: RacePolls[] = SEEDED_RACES;

const GENERATED = (generated.races ?? []) as unknown as RacePolls[];

/** When a pollster has more than one poll of a race, keep only their most recent
 *  (by field end date, then start date) — a fresh release supersedes the old
 *  one, so we don't show or average both. Input order is otherwise preserved. */
function latestPerPollster(polls: Poll[]): Poll[] {
  const key = (p: Poll) => p.pollster.trim().toLowerCase();
  const best = new Map<string, Poll>();
  for (const p of polls) {
    const cur = best.get(key(p));
    if (
      !cur ||
      p.endDate > cur.endDate ||
      (p.endDate === cur.endDate && (p.startDate ?? "") > (cur.startDate ?? ""))
    ) {
      best.set(key(p), p);
    }
  }
  return polls.filter((p) => best.get(key(p)) === p);
}

/** Two generated sources (RealClearPolling + Wikipedia) can cover the same
 *  race. Prefer RCP when it publishes an average for it; otherwise keep
 *  whichever has more polls (Wikipedia usually, for thinly-polled House races). */
function pickRace(a: RacePolls, b: RacePolls): RacePolls {
  const rcpAvg = (r: RacePolls) => r.source === "RealClearPolling" && !!r.aggregateAverage;
  if (rcpAvg(a) !== rcpAvg(b)) return rcpAvg(a) ? a : b;
  return b.polls.length > a.polls.length ? b : a;
}

/** All races: a pulled race replaces the seeded example with the same key. */
export const POLLS: RacePolls[] = (() => {
  const byKey = new Map<string, RacePolls>();
  for (const race of SEEDED) byKey.set(raceKey(race), race);
  const pulled = new Map<string, RacePolls>();
  for (const race of GENERATED) {
    const key = raceKey(race);
    const cur = pulled.get(key);
    pulled.set(key, cur ? pickRace(cur, race) : race);
  }
  for (const [key, race] of pulled) byKey.set(key, race);
  return [...byKey.values()].map((race) => ({
    ...race,
    polls: latestPerPollster(race.polls),
  }));
})();

/** When the generated data was last pulled, if ever. */
export const POLLS_GENERATED_AT: string | null = generated.generatedAt ?? null;

/**
 * Fold polls submitted by hand at /polls/submit (read from D1 at request
 * time by /polls's own loader) into `POLLS`, keyed the same way — a
 * submission for a race not in `POLLS` at all is silently dropped (the
 * submit form only offers races already tracked here, so this shouldn't
 * happen in practice). Re-runs `latestPerPollster` on any race that gained
 * polls, same rule as the SEEDED/GENERATED merge above.
 */
export function mergeManualPolls(
  base: RacePolls[],
  manualByKey: Record<string, Poll[]>
): RacePolls[] {
  if (Object.keys(manualByKey).length === 0) return base;
  return base.map((race) => {
    const extra = manualByKey[raceKey(race)];
    if (!extra || extra.length === 0) return race;
    return { ...race, polls: latestPerPollster([...race.polls, ...extra]) };
  });
}

/** Most recent poll end date across a race, for sorting. */
export function latestPollDate(race: RacePolls): string {
  return race.polls.reduce((max, p) => (p.endDate > max ? p.endDate : max), "");
}

/** Simple average margin (first candidate minus second) across a race's polls. */
export function averageMargin(race: RacePolls): number | null {
  if (race.polls.length === 0 || race.candidates.length < 2) return null;
  const [a, b] = race.candidates;
  const diffs = race.polls
    .map((poll) => {
      const pa = poll.results.find((r) => r.candidate === a.name)?.pct;
      const pb = poll.results.find((r) => r.candidate === b.name)?.pct;
      return pa != null && pb != null ? pa - pb : null;
    })
    .filter((d): d is number => d != null);
  if (diffs.length === 0) return null;
  return diffs.reduce((s, d) => s + d, 0) / diffs.length;
}
